ALTER TABLE public.jobs ADD COLUMN claim_hold boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.guard_dispatch_availability() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.scheduled_date IS NULL THEN NEW.open_to_claim=false; NEW.window_start=NULL; NEW.window_end=NULL; ELSIF NEW.claim_hold THEN NEW.open_to_claim=false; ELSIF NEW.assigned_technician_id IS NULL AND public.company_module_access(NEW.company_id,'skills_dispatch') THEN NEW.open_to_claim=true; END IF; RETURN NEW; END $$;
CREATE TRIGGER jobs_dispatch_availability BEFORE INSERT OR UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.guard_dispatch_availability();
DO $migration$ DECLARE f text; BEGIN
f=pg_get_functiondef('public.open_jobs_for_me()'::regprocedure);
f=replace(f,'AND j.open_to_claim AND public.member_is_active(auth.uid())', 'AND j.open_to_claim AND j.scheduled_date IS NOT NULL AND public.is_dispatchable_member(auth.uid(),j.company_id) AND EXISTS(SELECT 1 FROM public.shifts sh WHERE sh.user_id=auth.uid() AND sh.company_id=j.company_id AND sh.ended_at IS NULL AND sh.shift_type IN (''shift'',''standby'')) AND NOT EXISTS(SELECT 1 FROM public.job_sheets sheet WHERE sheet.job_id=j.id AND sheet.status=''completed'') AND public.member_is_active(auth.uid())');
f=replace(f,'ORDER BY j.scheduled_date','AND j.required_team_size > ((j.assigned_technician_id IS NOT NULL)::int + (j.secondary_technician_id IS NOT NULL)::int + (SELECT count(*) FROM public.job_crew x WHERE x.job_id=j.id)::int) ORDER BY j.scheduled_date'); EXECUTE f;
f=pg_get_functiondef('public.claim_open_job(uuid)'::regprocedure);
f=replace(f,'IF NOT j.open_to_claim THEN','IF j.scheduled_date IS NULL OR NOT public.is_dispatchable_member(me,j.company_id) OR EXISTS(SELECT 1 FROM public.job_sheets WHERE job_id=j.id AND status=''completed'') THEN RAISE EXCEPTION ''Job is not available''; END IF; IF NOT j.open_to_claim THEN'); EXECUTE f;
f=pg_get_functiondef('public.dispatch_pending_work(uuid,text,jsonb)'::regprocedure);
f=replace(f,'IF day IS NULL OR priority_value','IF priority_value');
f=replace(f,'existing.status NOT IN (''pending'',''draft'') OR ','');
f=replace(f,'j=public.route_pending_work(_sheet,''scheduled'',_expected,lead_id,day,''Dispatched follow-up visit'');','j=public.route_pending_work(_sheet,CASE WHEN day IS NULL THEN ''dispatch'' ELSE ''scheduled'' END,_expected,lead_id,day,''Dispatched follow-up visit'');');
f=replace(f,'UPDATE public.jobs SET secondary_technician_id=assistant_id','UPDATE public.jobs SET scheduled_date=day, secondary_technician_id=assistant_id'); EXECUTE f;
END $migration$;
CREATE OR REPLACE FUNCTION public.open_job_recipients(_job uuid) RETURNS TABLE(user_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT sh.user_id FROM public.jobs j JOIN public.shifts sh ON sh.company_id=j.company_id AND sh.ended_at IS NULL AND sh.shift_type IN ('shift','standby') WHERE j.id=_job AND j.company_id=public.current_company_id() AND public.member_dispatch_can() AND j.open_to_claim AND j.scheduled_date IS NOT NULL AND public.is_dispatchable_member(sh.user_id,j.company_id) AND sh.user_id IS DISTINCT FROM j.assigned_technician_id AND sh.user_id IS DISTINCT FROM j.secondary_technician_id AND NOT EXISTS(SELECT 1 FROM public.job_crew x WHERE x.job_id=j.id AND x.user_id=sh.user_id) AND NOT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.job_id=j.id AND s.status='completed') AND NOT EXISTS(SELECT 1 FROM public.job_skills k WHERE k.job_id=j.id AND k.mandatory AND NOT EXISTS(SELECT 1 FROM public.member_skills m WHERE m.user_id=sh.user_id AND m.skill_id=k.skill_id)); $$;
REVOKE ALL ON FUNCTION public.open_job_recipients(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_job_recipients(uuid) TO authenticated;